using Microsoft.Extensions.Logging.Abstractions;
using PlaylistSync.Core.Download;
using PlaylistSync.Core.Models;
using PlaylistSync.Core.Tools;

namespace PlaylistSync.Core.Tests;

public class BrowserCookieCacheTests : IDisposable
{
    internal const string Exported =
        "# Netscape HTTP Cookie File\n" +
        "# This file is generated by yt-dlp.  Do not edit.\n" +
        "\n" +
        ".youtube.com\tTRUE\t/\tTRUE\t1893456000\tSAPISID\tyt-secret\n" +
        "#HttpOnly_.youtube.com\tTRUE\t/\tTRUE\t1893456000\tLOGIN_INFO\tlogin\n" +
        "music.youtube.com\tFALSE\t/\tTRUE\t1893456000\tPREF\tx\r\n" +
        ".google.com\tTRUE\t/\tTRUE\t1893456000\tSID\tgoogle-secret\n" +
        "accounts.google.com\tFALSE\t/\tTRUE\t1893456000\tLSID\ty\n" +
        ".bank.example\tTRUE\t/\tTRUE\t1893456000\tsession\tbank-secret\n" +
        "#HttpOnly_mail.example.org\tFALSE\t/\tTRUE\t1893456000\tauth\tmail-secret\n" +
        ".notyoutube.com\tTRUE\t/\tTRUE\t1893456000\ta\tb\n" +
        "youtube.com.evil.net\tFALSE\t/\tTRUE\t1893456000\ta\tb\n";

    private static readonly ToolLocation YtDlp = new(ToolKind.YtDlp, "/usr/bin/yt-dlp", "yt-dlp", ToolSource.SystemPath);
    private static readonly DownloadOptions Brave = new() { CookieMode = CookieMode.Browser, CookiesBrowser = "brave" };

    private readonly TempDir _dir = new();
    private readonly ManualClock _clock = new();
    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    public void Dispose() => _dir.Dispose();

    private string CookieDir => _dir.File("cookies");

    private BrowserCookieCache Cache(FakeProcessRunner runner) =>
        new(runner, CookieDir, _clock, NullLogger<BrowserCookieCache>.Instance);

    /// <summary>Behaves like yt-dlp without a URL: writes the --cookies file, then fails with exit code 2.</summary>
    internal static FakeProcessRunner ExportingRunner(string content = Exported) => new(r =>
    {
        var args = r.Arguments.ToList();
        File.WriteAllText(args[args.IndexOf("--cookies") + 1], content);
        return new ProcessResult(2, "", "Extracted 9 cookies from brave\nUsage: yt-dlp [OPTIONS] URL\n\nyt-dlp: error: You must provide at least one URL.\n", TimeSpan.Zero);
    });

    [Fact]
    public void Filter_keeps_only_youtube_and_google_cookies()
    {
        var filtered = BrowserCookieCache.Filter(Exported, out var kept, out var total);

        Assert.Equal(9, total);
        Assert.Equal(5, kept);
        Assert.StartsWith("# Netscape HTTP Cookie File\n", filtered);
        Assert.Contains("SAPISID\tyt-secret", filtered);
        Assert.Contains("#HttpOnly_.youtube.com\t", filtered);
        Assert.Contains("music.youtube.com\t", filtered);
        Assert.Contains("SID\tgoogle-secret", filtered);
        Assert.Contains("accounts.google.com\t", filtered);
        Assert.DoesNotContain("bank-secret", filtered);
        Assert.DoesNotContain("mail-secret", filtered);
        Assert.DoesNotContain("notyoutube", filtered);
        Assert.DoesNotContain("evil.net", filtered);
        Assert.DoesNotContain("\r", filtered);
    }

    [Fact]
    public async Task Extracts_once_and_reuses_the_result()
    {
        var runner = ExportingRunner();
        var cache = Cache(runner);

        var first = await cache.GetAsync(Brave, YtDlp, Ct);
        _clock.Advance(BrowserCookieCache.MaxAge - TimeSpan.FromSeconds(1));
        var second = await cache.GetAsync(Brave, YtDlp, Ct);

        Assert.NotNull(first);
        Assert.Same(first, second);
        var request = Assert.Single(runner.Requests);
        Assert.Equal("/usr/bin/yt-dlp", request.FileName);
        Assert.Equal("brave", request.Arguments[request.Arguments.ToList().IndexOf("--cookies-from-browser") + 1]);
        // The unfiltered export is gone; nothing but the cookie folder is left.
        Assert.Empty(Directory.EnumerateFileSystemEntries(CookieDir));
    }

    [Fact]
    public async Task Extracts_again_after_max_age_invalidation_or_another_browser()
    {
        var runner = ExportingRunner();
        var cache = Cache(runner);

        await cache.GetAsync(Brave, YtDlp, Ct);
        _clock.Advance(BrowserCookieCache.MaxAge);
        await cache.GetAsync(Brave, YtDlp, Ct);
        Assert.Equal(2, runner.Requests.Count);

        cache.Invalidate();
        await cache.GetAsync(Brave, YtDlp, Ct);
        Assert.Equal(3, runner.Requests.Count);

        await cache.GetAsync(Brave with { CookiesBrowserProfile = "Profile 1" }, YtDlp, Ct);
        Assert.Equal(4, runner.Requests.Count);
        Assert.Contains("brave:Profile 1", runner.Requests[3].Arguments);
    }

    [Fact]
    public async Task Concurrent_callers_share_one_extraction()
    {
        var runner = ExportingRunner();
        var cache = Cache(runner);

        var all = await Task.WhenAll(Enumerable.Range(0, 4).Select(_ => cache.GetAsync(Brave, YtDlp, Ct)));

        Assert.Single(runner.Requests);
        Assert.All(all, s => Assert.Same(all[0], s));
    }

    [Theory]
    [InlineData(CookieMode.None, "brave")]
    [InlineData(CookieMode.File, "brave")]
    [InlineData(CookieMode.Browser, " ")]
    public async Task Returns_null_without_running_anything_when_not_reading_a_browser(CookieMode mode, string browser)
    {
        var runner = ExportingRunner();

        var snapshot = await Cache(runner).GetAsync(new DownloadOptions { CookieMode = mode, CookiesBrowser = browser }, YtDlp, Ct);

        Assert.Null(snapshot);
        Assert.Empty(runner.Requests);
    }

    [Fact]
    public async Task Returns_null_and_does_not_cache_when_the_export_fails()
    {
        var runner = new FakeProcessRunner(_ => FakeProcessRunner.Fail("ERROR: could not find brave cookies database", 1));
        var cache = Cache(runner);

        Assert.Null(await cache.GetAsync(Brave, YtDlp, Ct));
        Assert.Null(await cache.GetAsync(Brave, YtDlp, Ct));
        Assert.Equal(2, runner.Requests.Count);
    }

    [Fact]
    public async Task Copies_are_private_and_deleted_on_dispose()
    {
        var snapshot = (await Cache(ExportingRunner()).GetAsync(Brave, YtDlp, Ct))!;

        var a = snapshot.WriteCopy()!;
        var b = snapshot.WriteCopy()!;

        Assert.NotEqual(a.Path, b.Path);
        Assert.Equal(BrowserCookieCache.Filter(Exported, out _, out _), await File.ReadAllTextAsync(a.Path, Ct));
        if (!OperatingSystem.IsWindows())
        {
            Assert.Equal(UnixFileMode.UserRead | UnixFileMode.UserWrite, File.GetUnixFileMode(a.Path));
            Assert.Equal(UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute, File.GetUnixFileMode(CookieDir));
        }

        a.Dispose();
        Assert.False(File.Exists(a.Path));
        Assert.True(File.Exists(b.Path));
        b.Dispose();
    }

    [Fact]
    public void Cookie_file_replaces_the_browser_in_the_options()
    {
        using var file = new CookieFile(_dir.File("c.txt"));

        var applied = file.Apply(Brave with { CookiesBrowserProfile = "work", Proxy = "socks5://h:1" });

        Assert.Equal(CookieMode.File, applied.CookieMode);
        Assert.Equal(file.Path, applied.CookiesFile);
        Assert.Null(applied.CookiesBrowser);
        Assert.Equal("socks5://h:1", applied.Proxy);
        var args = YtDlpArgsBuilder.PlaylistFetch("https://youtu.be/x", applied, null);
        Assert.Contains("--cookies", args);
        Assert.DoesNotContain("--cookies-from-browser", args);
    }

    [Fact]
    public void Export_args_have_no_url()
    {
        Assert.Equal(["--ignore-config", "--cookies-from-browser", "firefox:work", "--cookies", "/run/c.txt"],
            YtDlpArgsBuilder.CookieExport("firefox:work", "/run/c.txt"));
    }

    [Theory]
    [InlineData("/run/user/1000", "/run/user/1000/playlist-sync/cookies")]
    [InlineData(null, "/data/playlist-sync/cookies")]
    [InlineData("relative", "/data/playlist-sync/cookies")]
    public void Default_directory_prefers_the_runtime_dir(string? runtime, string expected)
    {
        if (OperatingSystem.IsWindows()) return;
        var paths = new AppPaths("/config/playlist-sync", "/data/playlist-sync");

        Assert.Equal(expected, BrowserCookieCache.DefaultDirectory(paths, k => k == "XDG_RUNTIME_DIR" ? runtime : null));
    }

    internal sealed class ManualClock : TimeProvider
    {
        private DateTimeOffset _now = new(2026, 1, 1, 0, 0, 0, TimeSpan.Zero);
        public override DateTimeOffset GetUtcNow() => _now;
        public void Advance(TimeSpan by) => _now += by;
    }
}
